INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('acfc725a-edf9-58e3-9ac2-49bfea62cce6'::uuid, '17a019ab-e9bb-50d1-bf58-7d6a2c89a87d'::uuid, 'Réalisation — MADA Architectes', '304,Philips Business Center, 6 eme Etage, B n⁰609, Bd Mohamed V- CASABLANCA', '["https://lechantier.ma/uploads/media/2bf048a2445d.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/2bf048a2445d.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9fc0991e-b623-5a3b-8131-f881a2c80e0b'::uuid, '95eadfaa-5b62-5a29-a911-70eebeccf114'::uuid, 'Villa d’Exception à Marrakech – Élégance', 'Villa de luxe située à Marrakech au quartier Targa sur un terrain de 600 m², pensée pour offrir un cadre de vie exclusif et raffiné. Architecture contemporaine, volumes généreux, grandes ouvertures sur jardin et piscine privée. Finitions haut de gamme, harmonie entre confort moderne et élégance intemporelle.', '["https://lechantier.ma/uploads/media/db5dfc263791.webp", "https://lechantier.ma/uploads/media/bdd064f38924.webp", "https://lechantier.ma/uploads/media/60a14df121e1.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/db5dfc263791.webp', 'Berrechid', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3525ec6c-0e0b-5a06-95a1-26e4bc92cd58'::uuid, '95eadfaa-5b62-5a29-a911-70eebeccf114'::uuid, 'Projet de 28 villas de luxe – Marrakech', 'Situé à Al Ouidane, ce projet propose 28 villas de luxe de plain-pied, alliant confort moderne et élégance architecturale. Chaque villa offre un jardin paysager, une piscine privée et des espaces lumineux, dans un cadre paisible à proximité de Marrakech. Un art de vivre exclusif au cœur de la nature.', '["https://lechantier.ma/uploads/media/5712ad1479c7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5712ad1479c7.webp', 'Berrechid', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
