INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3b0ffb62-2c01-5b3a-841f-378ff86ab1ca'::uuid, '60000ad3-f422-5c71-962c-cf60d576eb71'::uuid, 'Projet Villa | Réception', 'Un espace de vie conçu autour d’une architecture intérieure sobre et maîtrisée. Lignes épurées, volumes ouverts et transitions fluides structurent l’ensemble et optimisent la lecture de l’espace. Entre tons neutres, matières naturelles et jeux de lumière, l’ambiance se veut à la fois chaleureuse et contemporaine. 📍 Casablanca', '["https://lechantier.ma/uploads/media/86fd2a34b7db.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/86fd2a34b7db.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5b64c2e5-7d65-584c-a863-15ff68ef6ca8'::uuid, '60000ad3-f422-5c71-962c-cf60d576eb71'::uuid, 'Moodboard Projet : Villa D', 'Un équilibre entre matières, formes sculpturales et lignes graphiques pour créer une atmosphère élégante et contemporaine. Un moodboard pensé comme une atmosphère : contemporaine, élégante et intemporelle.', '["https://lechantier.ma/uploads/media/03138cdf0c2c.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/03138cdf0c2c.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
