INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b5533830-99f2-55fc-9f73-1d1621614dae'::uuid, '542b3cfa-288a-5363-ad2a-96a92e59e1f4'::uuid, 'Coverage areas', 'Marrakech', '[]'::jsonb, NULL, 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('00bc08e5-107a-58fa-a702-55d454ccc723'::uuid, '2500709c-dd6b-57d9-b0ae-8b54d0508abd'::uuid, 'Plancher réticulé – Optimisation', 'Projet nécessitant de grandes portées sans poteaux intermédiaires. L’enjeu était de concilier performance structurelle et esthétique architecturale. Une solution en plancher réticulé a été adoptée permettant une réduction des charges et une meilleure flexibilité des espaces.', '["https://lechantier.ma/uploads/media/60ea4cedc2f5.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/60ea4cedc2f5.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f9d4a69d-2f11-5df4-b68c-a79c4b64f104'::uuid, '2500709c-dd6b-57d9-b0ae-8b54d0508abd'::uuid, 'Suivi travaux villa haut standing', 'Projet de suivi de travaux pour une villa haut standing. L’enjeu était d’assurer la qualité d’exécution et le respect des plans d’exécution. Un suivi technique rigoureux a permis d’éviter les erreurs et d’optimiser les délais de réalisation.', '[]'::jsonb, NULL, 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a36da8d0-3da9-5471-8669-12a4793f6a7f'::uuid, 'bd3fb837-0163-547b-84b2-58d027b3c697'::uuid, 'Réalisation — Amastroy Engineering & Consulting', NULL, '["https://lechantier.ma/uploads/media/1ede2d2053f0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/1ede2d2053f0.webp', 'Oujda', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('853c622f-dc29-5f51-9dfa-978ff665df63'::uuid, '7d483f90-c9ad-5c18-af8a-56eb83d10307'::uuid, '🔷 Villa à Marrakech | Rendu 3D & Visite', '🎯 Objectif : traduire l’intention architecturale en une expérience immersive, permettant au client de se projeter dans son futur lieu de vie. 💼 Mon rôle : assurer la production d’un rendu 3D réaliste et d’une visite virtuelle, en collaboration étroite avec l’architecte, tout en accompagnant le suivi de chantier pour garantir la cohérence entre', '["https://lechantier.ma/uploads/media/d3713230e929.webp", "https://lechantier.ma/uploads/media/a7708e8ef573.webp", "https://lechantier.ma/uploads/media/cbd9f387b2bd.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d3713230e929.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('260629fe-80d4-58a7-b959-79a60c4c87b0'::uuid, '7d483f90-c9ad-5c18-af8a-56eb83d10307'::uuid, '🔷 Villa à Casablanca Dar Bouazza | Rend', '🎯 Objectif : offrir au client une projection réaliste de son futur espace de vie. 💼 Mon rôle : collaborer avec l’architecte, réaliser un rendu 3D et une visite virtuelle, puis accompagner le suivi de chantier afin d’adapter la 3D à l’évolution réelle du projet. 📌 Discutons ensemble de vos futurs projets. Je suis toujours partant pour de nouvell', '["https://lechantier.ma/uploads/media/61b1e7e2c289.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/61b1e7e2c289.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a12af51a-f8d4-560d-a019-ca60b8428e9e'::uuid, '7d483f90-c9ad-5c18-af8a-56eb83d10307'::uuid, 'Réalisation — mooua design', NULL, '["https://lechantier.ma/uploads/media/a7708e8ef573.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/a7708e8ef573.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2193704b-acbd-5bdc-9226-98f71306aae4'::uuid, '7d483f90-c9ad-5c18-af8a-56eb83d10307'::uuid, 'Réalisation — mooua design', NULL, '["https://lechantier.ma/uploads/media/cbd9f387b2bd.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cbd9f387b2bd.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('093bcaaa-b6a9-59c0-8455-0bab2825efea'::uuid, '57d687c2-4f7b-5ab4-878a-5c3906c007b0'::uuid, 'Ingénierie de Sécurité Incendie (CFD)', 'Projet hôtelier faisant l’objet d’une étude d’ingénierie de sécurité incendie par simulation numérique avancée CFD/FDS. L’étude a permis d’analyser la propagation des fumées, la visibilité, les concentrations de gaz toxiques et les conditions d’évacuation des occupants, afin de valider et optimiser les solutions de désenfumage.', '["https://lechantier.ma/uploads/media/ec2c740f998b.webp", "https://lechantier.ma/uploads/media/3fb97e9b9cdd.webp", "https://lechantier.ma/uploads/media/dd7b5bd7a15d.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ec2c740f998b.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e7303546-6658-5d07-bff0-75013b825fde'::uuid, '57d687c2-4f7b-5ab4-878a-5c3906c007b0'::uuid, 'Piscine semi-olympique', 'L''étude technique et la modélisation 3D : - Dimensionnement des pompes de recirculation ; - Dimensionement du systeme de filtration ; - Conception et dimesnionnement du système de traitement d''eau; - Dimensionnement de la chaufferie.', '["https://lechantier.ma/uploads/media/f6e7c29289cb.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f6e7c29289cb.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6a2ff3cc-1000-5250-b922-a0279da8348e'::uuid, '57d687c2-4f7b-5ab4-878a-5c3906c007b0'::uuid, 'Réalisation — TEEMLAN ENGINEERING SERVCIES', NULL, '["https://lechantier.ma/uploads/media/3fb97e9b9cdd.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3fb97e9b9cdd.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ec19057b-d7c0-5481-82d3-09f50d98a51c'::uuid, '57d687c2-4f7b-5ab4-878a-5c3906c007b0'::uuid, 'Réalisation — TEEMLAN ENGINEERING SERVCIES', NULL, '["https://lechantier.ma/uploads/media/dd7b5bd7a15d.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/dd7b5bd7a15d.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('0fbf7049-835f-5d90-88ca-0957514aa451'::uuid, '884bff55-fd44-5eee-9ba9-e9e5ea09e8bb'::uuid, 'Villa L - Marrakech', 'Villa contemporaine à Marrakech où matières naturelles et savoir-faire artisanal se rencontrent. Cannage, bois, pierre et teintes terreuses créent un univers authentique, épuré, inspiré des traditions locales revisitées avec modernité !', '["https://lechantier.ma/uploads/media/937dcc5726ec.webp", "https://lechantier.ma/uploads/media/2ef4269757b2.webp", "https://lechantier.ma/uploads/media/c4283436a566.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/937dcc5726ec.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d8041f40-e43d-5b8d-a2cd-5d2b61bffaa9'::uuid, '884bff55-fd44-5eee-9ba9-e9e5ea09e8bb'::uuid, 'Villa W - Rabat', 'Villa proposant des espaces où la modernité se conjugue avec des touches de tradition. Les lignes épurées, les matériaux nobles et les volumes ouverts s’harmonisent avec des éléments décoratifs et des ambiances inspirées des savoir-faire traditionnels. Une conception qui crée un équilibre subtil entre confort contemporain et héritage culturel.', '["https://lechantier.ma/uploads/media/ec11e7977451.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ec11e7977451.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
