INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('97da5846-a545-5648-b8e2-f5253e504f67'::uuid, 'c6b0828d-c932-5316-876a-4c487901fc32'::uuid, 'Restaurant casaemma', 'Le restaurant-lounge La Casa Emma à Rabat est une réalisation d''Archiste. Le projet marie le bohème-chic et le style méditerranéen autour d''une palette de couleurs dominée par le blanc épuré. L''ambiance est créée par des matériaux naturels : plafonds en paille tressée ou voilages drapés, mobilier en rotin/fibres naturelles, et végétation abondant', '["https://lechantier.ma/uploads/media/5ddfaa67b55f.webp", "https://lechantier.ma/uploads/media/5beb93ba18a4.webp", "https://lechantier.ma/uploads/media/570a966aaaa0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5ddfaa67b55f.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('868a1673-1cd2-58c3-b16a-227b186b520f'::uuid, 'c6b0828d-c932-5316-876a-4c487901fc32'::uuid, 'suite parentale de luxe MB', 'Ce projet d''Archiste est une suite parentale de luxe au design moderne et sophistiqué. La réalisation se distingue par l''usage de matériaux haut de gamme (bois sombre, marbre, travertin) dans une palette de couleurs neutres et riches. L''espace intègre un dressing vitré, un coin salon avec cheminée, et un éclairage LED discret, définissant une amb', '["https://lechantier.ma/uploads/media/9650285c22b4.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9650285c22b4.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
