INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d9fbc55c-0ff8-5cf0-b77d-ae10d054f32d'::uuid, '6fc5e188-20ac-54ff-ab94-2c23e62c088a'::uuid, 'BMCI - Data Center', 'Rénovation et aménagement du local technique et du Data Center de la BMCI. Conception d’un espace sécurisé, fonctionnel et moderne intégrant des armoires de précision, systèmes de contrôle, sécurité incendie et mobilier sur mesure pour la zone d’accueil technique.', '["https://lechantier.ma/uploads/media/cb2f98306318.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cb2f98306318.webp', 'Settat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5ff5e13a-2533-5620-a97f-02931003ee88'::uuid, '6fc5e188-20ac-54ff-ab94-2c23e62c088a'::uuid, 'SALON MAROCAIN MODERNE', 'Ce salon marocain moderne allie authenticité et élégance contemporaine. Les lignes épurées se marient aux motifs traditionnels, créant un équilibre harmonieux entre culture et modernité. Les tons neutres, les matériaux nobles et l’éclairage doux apportent chaleur et raffinement à l’espace.', '[]'::jsonb, NULL, 'Settat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
