INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5ae6b157-d849-5600-baf4-f84efc17d1fa'::uuid, '85fc3603-33f9-5d46-b036-4faa5573c53b'::uuid, 'DSBTM – Nos Services VRD & Structure', 'Bureau d''Études Technique DSBTM – De la conception à la réalisation. NOS SERVICES: • Études VRD (voirie, réseaux divers) • Assainissement & eau potable • Éclairage public • Études structure béton armé R+4 • Plans de coffrage & ferraillage • Note de calcul RPS 2000 • Suivi de chantier Zones: Benslimane, Casablanca, Rabat, Mohammedia. Devis gratuit sous 24h – WhatsApp direct.', '["https://lechantier.ma/uploads/media/5443a1bb43c9.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5443a1bb43c9.webp', 'Benslimane', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('96fbcb23-8389-5411-ba9e-787bdaab3f31'::uuid, '85fc3603-33f9-5d46-b036-4faa5573c53b'::uuid, 'Étude Structure Béton Armé – Immeuble R+4', 'Mission complète d''études techniques pour immeuble R+4 à usage mixte. Calcul structure selon RPS 2000 v2011, plans de coffrage, ferraillage poteaux-poutres-dalles, note de calcul et descente de charges. Plans d''exécution livrés sous AutoCAD et PDF, avec suivi chantier jusqu''au gros œuvre. Délai: 12 jours', '[]'::jsonb, NULL, 'Benslimane', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
